<template>
  <main ref="pageRoot" class="expert-library" v-loading="loading">
    <template v-if="!activeExpert">
      <header class="page-heading"><div><div class="eyebrow">AI 管理决策</div><h1>专家团</h1><p>从需要解决的管理问题出发，选择专家查看数据、分析依据和下一步建议。</p></div><div class="header-links"><el-button v-if="catalog.canManage" @click="router.push('/admin/system/expert-management')">管理专家</el-button><el-button @click="router.push('/admin/reports/expert-team/legacy')">原研究工作区</el-button></div></header>
      <div v-if="error" class="notice" :class="{error:!error.startsWith('已')}" :role="error.startsWith('已')?'status':'alert'">{{ error }} <el-button link @click="load">重新加载</el-button></div>
      <nav class="tabs" aria-label="专家团工作区"><button :class="{active:tab==='library'}" @click="tab='library'">专家库</button><button :class="{active:tab==='research'}" @click="tab='research';loadHistory()">我的研究 <span>{{ history.length }}</span></button></nav>
      <template v-if="tab==='library'"><div class="toolbar"><el-input v-model="search" clearable placeholder="搜索专家或管理问题，例如培养方案、课程质量" aria-label="搜索专家" /><el-select v-model="category" clearable placeholder="全部业务分类" aria-label="专家业务分类"><el-option v-for="value in categories" :key="value" :value="value" :label="value" /></el-select></div><div class="expert-grid"><article v-for="expert in filtered" :key="expert.id" class="expert-card"><div class="card-content"><div class="expert-heading"><div class="avatar" aria-hidden="true">{{ expert.name.slice(0,1) }}</div><div><h2>{{ expert.name }}</h2><span class="category">{{ expert.category }}</span></div></div><p>{{ businessContent(expert).summary || expert.summary }}</p><div class="capabilities"><span v-for="skill in expertSkills(expert).slice(0,3)" :key="skill.id">{{ skill.name }}</span></div><p class="availability" :class="{warn:!canStart(expert)}">{{ availability(expert) }}</p></div><footer><el-button link @click="detail=expert">查看职责与边界</el-button><el-button type="primary" plain :disabled="!canStart(expert)" @click="start(expert)">开始研究</el-button></footer></article></div><el-empty v-if="!loading&&!filtered.length" description="未找到相关专家，试试其他管理问题" /></template>
      <template v-else><div class="toolbar"><el-input v-model="historySearch" clearable placeholder="搜索我的研究" aria-label="搜索研究记录" /><el-button @click="loadHistory">刷新</el-button></div><div v-if="historyError" class="notice error" role="alert">{{ historyError }}</div><section class="history-list"><button v-for="research in filteredHistory" :key="research.id" class="history-item" @click="resume(research.id)"><span><b>{{ research.title || '未命名研究' }}</b><small>{{ research.expertName || expertName(research.expertId) }} · 规则 v{{ research.expertVersion }} · {{ date(research.updatedAt || research.createdAt) }}</small></span><span>{{ research.turnCount || research.turns?.length || 0 }} 轮分析 <span aria-hidden="true">→</span></span></button><el-empty v-if="!filteredHistory.length" description="暂无研究记录。从专家库选择专家开始。" /></section></template>
      <p class="page-note">业务数据来自 114 测试环境，按当前授权范围只读查询。历史研究保留当时结果，继续分析读取当前数据。</p>
    </template>
    <template v-else>
      <button class="back-link" :disabled="running" @click="leave">← 返回{{ currentResearch ? '我的研究' : '专家库' }}</button><header class="page-heading"><div><div class="eyebrow">{{ activeExpert.name }} · {{ currentResearch ? `研究 ${currentResearch.id}` : '新研究' }}</div><h1>{{ currentResearch?.title || '准备本次研究' }}</h1><p>规则 v{{ currentResearch?.expertVersion || activeExpert.published?.version }} · {{ currentResearch ? '继续使用本研究固定的资源版本' : '采用当前已发布的资源版本' }}</p></div><el-button @click="detail=activeExpert">职责与适用边界</el-button></header>
      <div v-if="error" class="notice" :class="{error:!error.startsWith('已')}" :role="error.startsWith('已')?'status':'alert'">{{ error }}</div><div v-if="currentResearch && activeExpert.published && currentResearch.expertVersion!==activeExpert.published.version" class="notice warning">保存研究使用原版本。当前已发布新版本 v{{ activeExpert.published.version }}，原结果不会变更。<el-button @click="start(activeExpert)">使用当前版本新建分析</el-button></div>
      <div class="research-layout"><aside class="research-inputs"><section ref="inputsPanel" class="panel" tabindex="-1"><h2>{{ currentResearch ? '下一轮分析范围' : '研究问题与范围' }}</h2><div class="entry-modes"><el-radio-group v-model="mode" :disabled="running"><el-radio-button value="selected_task">选择业务任务</el-radio-button><el-radio-button value="question" :disabled="!modelAvailable">直接提问</el-radio-button></el-radio-group><p v-if="!modelAvailable" class="execution-note">直接提问需要接通本专家配置的真实模型。</p></div><label v-if="mode==='selected_task'" class="field"><span>要分析什么</span><el-select v-model="taskId" placeholder="选择业务任务" :disabled="running" @change="input={}"><el-option v-for="task in availableTasks" :key="task.taskId" :value="task.taskId" :label="task.title" :disabled="!task.available" /></el-select></label><p v-if="selectedTask" class="method-note">{{ selectedTask.available?'按以下范围执行真实业务分析':selectedTask.reason }}</p><details v-if="availableTasks.some(t=>!t.available)" class="execution-note"><summary>尚未具备的任务</summary><p v-for="task in availableTasks.filter(t=>!t.available)" :key="task.taskId">{{ task.title }}：{{ task.reason }}</p></details><ScopeInputs v-model="input" :schema="selectedSchema" :disabled="running" :options="options" :loading="optionsLoading" :failed="!!optionsError" compact :course-loading="coursesLoading" :course-error="coursesError" /><div v-if="coursesError" class="notice warning">{{ coursesError }} <el-button link @click="loadCourseOptions">重试课程选项</el-button></div><p v-for="problem in researchProblems" :key="problem" class="execution-note">{{ problem }}</p><div v-if="optionsError" class="notice warning">{{ optionsError }} <el-button link @click="loadOptions">重试</el-button></div><details v-if="mode==='selected_task'" class="context-details" :open="!!question"><summary>补充背景（可选）</summary><label class="field question-field"><span>本轮背景说明</span><el-input v-model="question" type="textarea" :rows="3" maxlength="1500" show-word-limit placeholder="补充希望关注的情况；实际分析以所选业务任务和范围为准" :disabled="running" /></label></details><label v-else class="field question-field"><span>你的管理问题</span><el-input v-model="question" type="textarea" :rows="4" maxlength="1500" show-word-limit placeholder="写下希望了解的管理问题" :disabled="running" /></label><div v-if="mode==='question' && !currentResearch && businessContent(activeExpert).starterQuestions?.length" class="starters"><button v-for="item in businessContent(activeExpert).starterQuestions?.slice(0,2)" :key="item" @click="question=item">{{ item }}</button></div><el-button type="primary" class="run-button" :loading="running" :disabled="running || coursesLoading && !!input.course_id || researchProblems.length>0 || (mode==='selected_task'?!selectedTask?.available:!modelAvailable||!question.trim())" @click="run">{{ currentResearch ? '继续分析并保存' : '开始分析并保存' }}</el-button><p class="execution-note">选任务按明示范围执行，补充说明保存为背景；直接提问由真实模型识别任务，关键歧义需先确认。</p></section><section v-if="turns.length" ref="turnsPanel" class="panel turn-list" tabindex="-1"><h2>本次研究记录</h2><button v-for="(turn,index) in turns" :key="turn.id || index" :class="{selected:selectedTurn===index}" @click="showTurn(index)"><span>第 {{ index+1 }} 轮 · {{ stateLabels[turn.execution?.state || turn.state] || (turn.status==='passed'?'已完成':turn.status==='blocked'?'条件未满足':'已保存回复') }}</span><b>{{ turn.question || turn.summary || '本轮分析' }}</b><small>{{ date(turn.createdAt) }}</small></button></section></aside>
        <section ref="resultArea" class="result-area" tabindex="-1"><div v-if="running" class="running-state" role="status"><el-icon class="is-loading"><Loading /></el-icon><span>{{ stateLabels[execution?.state || 'queued'] }}：正在核对范围、依赖和真实数据</span><el-button @click="cancel" :disabled="!execution">取消本次执行</el-button></div><section v-if="displayedExecution && !running && !currentResultId" class="notice" :class="{warning:['needs_input','partial','blocked'].includes(displayedExecution.state),error:displayedExecution.state==='failed'}"><b>{{ stateLabels[displayedExecution.state] }}</b><p>{{ displayedExecution.summary }}</p><small v-if="displayedExecution.failureCode">原因：{{ displayedExecution.failureCode }}</small><el-button v-if="['failed','blocked','cancelled'].includes(displayedExecution.state) && pendingRequest" @click="retry">按原问题重新执行</el-button></section><section v-if="clarification" class="panel"><h2>确认一个必要条件</h2><p>{{ clarification.question }}</p><el-select v-if="clarification.options?.length" v-model="answer" placeholder="选择答案"><el-option v-for="option in clarification.options" :key="typeof option==='string'?option:option.id" :value="typeof option==='string'?option:option.id" :label="typeof option==='string'?option:option.label" /></el-select><el-input v-else v-model="answer" placeholder="补充所需条件" /><el-button type="primary" :disabled="!answer.trim()||running" @click="answerClarification">确认并继续原问题</el-button></section><el-button v-if="error && !error.startsWith('已') && pendingRequest && !running" @click="recover">查询原任务／原请求</el-button><div v-if="latestAnalysisIndex>=0&&selectedTurn!==latestAnalysisIndex" class="notice"><span>当前查看第 {{ selectedTurn+1 }} 轮{{ currentResultId ? '保存结果' : '回复' }}；最近有效分析结果在第 {{ latestAnalysisIndex+1 }} 轮。</span><el-button link @click="showTurn(latestAnalysisIndex)">查看最近有效结果</el-button></div><div v-if="currentResultId" class="saved-result" role="status"><span>第 {{ selectedTurn+1 }} 轮结果已保存到“我的研究”</span><div><el-button link @click="focusPanel(inputsPanel)">调整下一轮范围</el-button><el-button link @click="focusPanel(turnsPanel)">查看研究记录</el-button></div></div><article v-if="currentTurn" class="panel result-panel"><div class="question-record"><span>本轮问题</span><p>{{ currentTurn.question }}</p></div><RunResult :run="currentTurn" :options="options" :version="currentResearch?.expertVersion" mode="research" :allow-course-analysis="currentTurn.input?.taskId==='C-PERFORMANCE'" @inspect-course="prepareCourse" @show-issues="focusPanel(issuesPanel)" /></article><article v-if="currentResearch" ref="issuesPanel" class="panel" tabindex="-1"><ResearchIssues :research-id="currentResearch.id" :refresh="currentResearch.turns?.length" @recheck="prepareRecheck" /></article><div v-else class="panel empty-research"><div class="empty-icon" aria-hidden="true">研</div><h2>先选择研究事项与数据范围</h2><p>执行后可在这里查看分析结果、数据明细、来源和所用方法。</p><ul><li>数据查询按当前登录身份授权范围执行。</li><li>结果用于辅助判断，资料不足时列出具体缺项。</li><li>每轮执行结果保存到“我的研究”，可继续追踪。</li></ul></div></section></div>
    </template>
    <el-dialog v-model="detailOpen" :title="detail?.name || '专家职责'" width="min(790px,94vw)" append-to-body><template v-if="detail"><p class="detail-purpose">{{ businessContent(detail).summary || detail.summary }}</p><section class="detail-section"><h3>具体职责</h3><ul><li v-for="item in businessContent(detail).responsibilities || []" :key="item">{{ item }}</li></ul></section><section class="detail-section"><h3>可研究的事项</h3><article v-for="skill in expertSkills(detail)" :key="skill.id" class="skill-summary"><b>{{ skill.name }}</b><span>{{ skill.published ? `v${skill.published.version}` : '尚未发布' }}</span><p>{{ businessContent(skill).summary || skill.summary }}</p><p v-if="businessContent(skill).missingEvidence?.length" class="missing">还需：{{ businessContent(skill).missingEvidence?.join('；') }}</p></article></section><section class="detail-section"><h3>适用边界</h3><ul><li v-for="item in businessContent(detail).boundaries || []" :key="item">{{ item }}</li></ul></section><p class="notice" :class="{warning:!canStart(detail)}">{{ availability(detail) }}</p></template><template #footer><el-button @click="detail=null">关闭</el-button><el-button v-if="detail" type="primary" :disabled="!canStart(detail)" @click="start(detail);detail=null">开始研究</el-button></template></el-dialog>
  </main>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { authStore } from '@/store/auth'
import { Loading } from '@element-plus/icons-vue'
import { expertResourcesApi as api } from '@/api/aiDecision/expertResources'
import type { ExpertResource, ResourceCatalog, ResourceContent, ResourceOptions, ResourceResearch, ResourceRun, BusinessTask, ExpertModel, ExpertExecution, ExecutionRequest } from '@/types/expertResources'
import ScopeInputs from '../expert-resources/ScopeInputs.vue'
import RunResult from '../expert-resources/RunResult.vue'
import ResearchIssues from '../expert-resources/ResearchIssues.vue'
import {inputProblems} from '../expert-resources/presentation'
const props=defineProps<{initialExpertId?:string}>()
const router=useRouter()
const tasks=ref<BusinessTask[]>([]),models=ref<ExpertModel[]>([]),taskId=ref(''),mode=ref<'selected_task'|'question'>('selected_task'),execution=ref<ExpertExecution|null>(null),pendingRequest=ref<ExecutionRequest|null>(null),answer=ref('')
let generation=0,pollTimer:ReturnType<typeof setTimeout>|undefined
const recheckOriginalTurnId=ref<string|undefined>()
const pageRoot=ref<HTMLElement|null>(null)
const resultArea=ref<HTMLElement|null>(null),inputsPanel=ref<HTMLElement|null>(null),turnsPanel=ref<HTMLElement|null>(null),issuesPanel=ref<HTMLElement|null>(null)
async function focusPanel(panel:HTMLElement|null){await nextTick();panel?.scrollIntoView({block:'start',behavior:'auto'});panel?.focus({preventScroll:true})}
async function showTurn(index:number){selectedTurn.value=index;await nextTick();void focusPanel(resultArea.value)}
const terminal=new Set(['needs_input','completed','partial','blocked','failed','cancelled'])
const stateLabels:Record<string,string>={queued:'等待执行',running:'正在分析',needs_input:'需要补充条件',completed:'已完成',partial:'部分结果',blocked:'条件未满足',failed:'执行失败',cancelled:'已取消'}
const availableTasks=computed(()=>tasks.value.filter(t=>t.expertId===activeExpert.value?.id))
const selectedTask=computed(()=>availableTasks.value.find(t=>t.taskId===taskId.value))
const modelAvailable=computed(()=>!!activeExpert.value&&models.value.some(m=>m.id===businessContent(activeExpert.value!).modelId&&m.enabled!==false&&m.available!==false))
const clarification=computed(()=>execution.value?.clarification||execution.value?.outcome?.clarification||execution.value?.outcome?.result?.clarification)
const selectedSchema=computed(()=>selectedTask.value?.inputSchema||selectedSkill.value?.content.inputSchema)

const catalog=ref<ResourceCatalog>({experts:[],skills:[],mcps:[]}),options=ref<ResourceOptions>({plans:[],semesters:[],colleges:[],courses:[]}),history=ref<ResourceResearch[]>([])
const loading=ref(false),running=ref(false),error=ref(''),historyError=ref(''),optionsError=ref(''),optionsLoading=ref(false),tab=ref('library'),search=ref(''),category=ref(''),historySearch=ref('')
const activeExpert=ref<ExpertResource|null>(null),currentResearch=ref<ResourceResearch|null>(null),detail=ref<ExpertResource|null>(null),skillId=ref(''),input=ref<Record<string,unknown>>({}),question=ref(''),selectedTurn=ref(0)
const detailOpen=computed({get:()=>!!detail.value,set:value=>{if(!value)detail.value=null}})
const categories=computed(()=>[...new Set(catalog.value.experts.map(item=>item.category).filter(Boolean))])
const filtered=computed(()=>catalog.value.experts.filter(item=>(!category.value||item.category===category.value)&&(!search.value||`${item.name} ${item.summary} ${(businessContent(item).responsibilities||[]).join(' ')}`.toLowerCase().includes(search.value.toLowerCase()))))
const filteredHistory=computed(()=>history.value.filter(item=>!historySearch.value||`${item.title} ${expertName(item.expertId)}`.includes(historySearch.value)))
const currentSkills=computed(()=>{const pinned=currentResearch.value?.dependencies?.skills;if(Array.isArray(pinned))return pinned.map((item:any)=>({id:item.id,name:item.content?.name||catalog.value.skills.find(skill=>skill.id===item.id)?.name||item.id,content:item.content as ResourceContent,version:item.version}));return activeExpert.value?expertSkills(activeExpert.value).filter(item=>item.published&&item.enabled).map(item=>({id:item.id,name:item.name,content:item.published!.content,version:item.published!.version})):[]})
const selectedSkill=computed(()=>currentSkills.value.find(item=>item.id===skillId.value))
const researchProblems=computed(()=>mode.value==='question'?[]:inputProblems(selectedSchema.value,input.value))
const turns=computed<Array<ResourceRun&{question?:string}>>(()=>(currentResearch.value?.turns||[]).map((turn:any)=>turn.run?{...turn.run,question:turn.question}:{...turn}))
const currentTurn=computed(()=>turns.value[selectedTurn.value])
const currentResultId=computed(()=>currentTurn.value?.resultId||currentTurn.value?.execution?.resultId||currentTurn.value?.result?.resultId)
const displayedExecution=computed(()=>currentTurn.value?.execution||(!currentTurn.value?execution.value:null))
const latestAnalysisIndex=computed(()=>{for(let i=turns.value.length-1;i>=0;i--){const turn=turns.value[i];if(turn.resultId||turn.execution?.resultId||turn.status==='passed')return i}return -1})
const businessContent=(item:ExpertResource):ResourceContent=>item.published?.content||item.draft.content
const expertName=(id:string)=>catalog.value.experts.find(item=>item.id===id)?.name||id
function expertSkills(expert:ExpertResource){const ids=businessContent(expert).skillIds||[];return ids.map(id=>catalog.value.skills.find(item=>item.id===id)).filter((item):item is ExpertResource=>!!item)}
function canStart(expert:ExpertResource){return expert.enabled&&!!expert.published&&expertSkills(expert).some(skill=>skill.enabled&&skill.published)&&expert.readiness?.canRun!==false}
function availability(expert:ExpertResource){if(!expert.enabled)return '当前已停用，可查看职责与适用范围';if(!expert.published)return '资源待测试发布，暂不能开始研究';if(!expertSkills(expert).some(skill=>skill.enabled&&skill.published))return '所需 Skill 尚未发布或已停用';if(expert.readiness?.canRun===false)return expert.readiness.runReasons?.[0]||'当前运行条件未满足';const missing=expertSkills(expert).flatMap(skill=>businessContent(skill).missingEvidence||[]);return missing.length?`部分事项需要补充资料：${missing[0]}`:'可以开始研究，具体结论依本次数据与资料条件确定'}
const date=(value?:string)=>!value?'':Number.isNaN(new Date(value).getTime())?value:new Date(value).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})
async function load(){loading.value=true;error.value='';try{const [resources,taskList,modelList]=await Promise.all([api.catalog(),api.tasks(),api.models()]);catalog.value=resources;tasks.value=taskList.items;models.value=modelList.items}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function loadHistory(){historyError.value='';try{const result=await api.researchList();history.value=Array.isArray(result)?result:result.items||[]}catch(e){historyError.value=(e as Error).message}}
let optionsRequest = 0
async function loadOptions(){
  const requestId=++optionsRequest
  optionsLoading.value=true
  optionsError.value=''
  try{
    const result=await api.options()
    if(requestId===optionsRequest)options.value={...result,courses:options.value.courses||[]}
  }catch(e){
    if(requestId===optionsRequest)optionsError.value=`范围选项未加载：${(e as Error).message}`
  }finally{
    if(requestId===optionsRequest)optionsLoading.value=false
  }
}
const coursesLoading=ref(false),coursesError=ref('');let coursesRequest=0
async function loadCourseOptions(){
  const requestId=++coursesRequest
  coursesError.value='';options.value={...options.value,courses:[]}
  const semesterId=String(input.value.semester_id||''),collegeId=String(input.value.college_id||'')
  if(!activeExpert.value||!selectedSchema.value?.properties?.course_id||!semesterId){coursesLoading.value=false;return}
  coursesLoading.value=true
  try{const result=await api.courseOptions(semesterId,collegeId||undefined);if(requestId!==coursesRequest)return
    options.value={...options.value,courses:result.items}
    if(input.value.course_id&&!result.items.some(course=>String(course.id)===String(input.value.course_id))){const next={...input.value};delete next.course_id;input.value=next;error.value='已清除新范围内没有统计的课程筛选，请重新选择课程或查看全部课程。'}
  }catch(e){if(requestId===coursesRequest)coursesError.value=`课程选项未加载：${(e as Error).message}`}
  finally{if(requestId===coursesRequest)coursesLoading.value=false}
}
watch(()=>[activeExpert.value?.id,taskId.value,input.value.semester_id,input.value.college_id],()=>{void loadCourseOptions()})
function prepareCourse(row:Record<string,unknown>){
  if(running.value||!currentTurn.value)return
  recheckOriginalTurnId.value=undefined;input.value={...currentTurn.value.input,course_id:String(row.course_id)};taskId.value='C-PERFORMANCE';mode.value='selected_task'
  question.value=`查看${row.course_name||row.course_id}的首修表现`;error.value='已加载单课范围，请核对学期后开始新一轮分析。';void nextTick(()=>focusPanel(inputsPanel.value))
}
function start(expert:ExpertResource){if(!canStart(expert))return;recheckOriginalTurnId.value=undefined;generation++;clearTimeout(pollTimer);execution.value=null;pendingRequest.value=null;taskId.value=tasks.value.find(t=>t.expertId===expert.id&&t.available)?.taskId||'';mode.value='selected_task';activeExpert.value=expert;currentResearch.value=null;skillId.value=expertSkills(expert).find(item=>item.enabled&&item.published)?.id||'';input.value={};question.value='';selectedTurn.value=0;error.value='';void loadOptions();void nextTick(()=>pageRoot.value?.scrollTo({top:0,behavior:'auto'}))}
function leave(){if(running.value)return;generation++;clearTimeout(pollTimer);execution.value=null;pendingRequest.value=null;tab.value=currentResearch.value?'research':'library';activeExpert.value=null;currentResearch.value=null;error.value='';void loadHistory()}
async function resume(id:string){recheckOriginalTurnId.value=undefined;loading.value=true;error.value='';try{const research=await api.research(id);const expert=catalog.value.experts.find(item=>item.id===research.expertId)||{id:research.expertId,kind:'experts' as const,name:research.expertName||research.expertId,summary:'历史保存结果',category:'',enabled:false,draft:{version:research.expertVersion||'历史版本',revision:1,content:{name:research.expertName||research.expertId,skillIds:(research.dependencies?.skills||[]).map((item:any)=>item.id)}},readiness:{canRun:false,runReasons:['当前专家已删除或不可见，历史结果保留可读']}};activeExpert.value=expert;currentResearch.value=research;input.value={...(research.input||research.turns?.[research.turns.length-1]?.input||{})};skillId.value=String(input.value.skill_id||research.dependencies?.skills?.[0]?.id||'');taskId.value=String(input.value.taskId||tasks.value.find(t=>t.expertId===expert.id&&t.skillId===skillId.value)?.taskId||'');execution.value=null;pendingRequest.value=null;generation++;clearTimeout(pollTimer);question.value='';selectedTurn.value=Math.max((research.turns?.length||0)-1,0);const latest=research.turns?.at(-1);const executionRefId=latest?.executionId||latest?.execution?.id;if(executionRefId){running.value=true;void pollExecution(String(executionRefId),generation)}void loadOptions()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}

function executionId(value:ExpertExecution){return value.id||value.executionId||''}
async function updateExecution(value:ExpertExecution,epoch:number){
  if(epoch!==generation)return
  execution.value=value
  if(terminal.has(value.state)){
    clearTimeout(pollTimer);running.value=false
    if(value.researchId){const research=await api.research(value.researchId);if(epoch!==generation)return;currentResearch.value=research;selectedTurn.value=Math.max((currentResearch.value.turns?.length||0)-1,0)}
    if(['completed','partial'].includes(value.state)){question.value='';recheckOriginalTurnId.value=undefined}
    await loadHistory()
    await nextTick();if(epoch===generation)void focusPanel(resultArea.value)
    return
  }
  pollTimer=setTimeout(()=>{void pollExecution(executionId(value),epoch)},1000)
}
async function pollExecution(id:string,epoch:number){
  try{await updateExecution(await api.execution(id),epoch)}catch(e){if(epoch!==generation)return;running.value=false;error.value=`状态查询中断，任务可能仍在执行。请查询原任务：${(e as Error).message}`}
}
async function submitRequest(request:ExecutionRequest){
  const epoch=++generation;clearTimeout(pollTimer);running.value=true;error.value='';pendingRequest.value=request
  try{await updateExecution(await api.execute(request),epoch)}catch(e){if(epoch!==generation)return;running.value=false;error.value=`提交结果未确认，请查询原请求后再继续：${(e as Error).message}`}
}
function prepareRecheck(turnId?:string){const turn=turns.value.find(item=>item.id===turnId)||currentTurn.value;if(!turn)return;recheckOriginalTurnId.value=turn.id;input.value={...(turn.input||{})};taskId.value=String(input.value.taskId||taskId.value);question.value=turn.question||'';mode.value='selected_task';error.value='已加载原问题与范围，请核对补充后的条件并开始新一轮核验。';void nextTick(()=>focusPanel(inputsPanel.value))}
async function run(){
  if(!activeExpert.value||running.value||researchProblems.value.length)return
  if(mode.value==='question'&&!modelAvailable.value)return
  if(mode.value==='selected_task'&&!selectedTask.value?.available)return
  const text=question.value.trim()||selectedTask.value?.title||''
  if(!text)return
  await submitRequest({clientRequestId:crypto.randomUUID(),expertId:activeExpert.value.id,researchId:currentResearch.value?.id,expectedTurn:currentResearch.value?.turns?.length||0,mode:mode.value,question:text,originalTurnId:mode.value==='selected_task'?recheckOriginalTurnId.value:undefined,input:mode.value==='selected_task'?{...input.value,taskId:taskId.value}: {...input.value}})
}
async function recover(){if(!pendingRequest.value)return;if(execution.value&&executionId(execution.value)){running.value=true;await pollExecution(executionId(execution.value),generation)}else await submitRequest(pendingRequest.value)}
async function retry(){if(!pendingRequest.value||!execution.value||!['failed','blocked','cancelled'].includes(execution.value.state))return;await submitRequest({...pendingRequest.value,clientRequestId:crypto.randomUUID(),expectedTurn:currentResearch.value?.turns?.length||0,researchId:execution.value.researchId,retryOfExecutionId:executionId(execution.value)})}
async function cancel(){if(!execution.value)return;try{await updateExecution(await api.cancelExecution(executionId(execution.value)),generation)}catch(e){error.value=(e as Error).message}}
async function answerClarification(){if(!activeExpert.value||!clarification.value||!execution.value||!answer.value.trim())return;await submitRequest({clientRequestId:crypto.randomUUID(),expertId:activeExpert.value.id,researchId:execution.value.researchId,expectedTurn:currentResearch.value?.turns?.length||0,mode:'clarification_answer',question:pendingRequest.value?.question||currentTurn.value?.question||'',input:{},originalTurnId:execution.value.turnId,clarificationId:clarification.value.clarificationId,answer:answer.value});answer.value=''}
watch(selectedTask,task=>{skillId.value=task?.skillId||skillId.value})
watch(selectedSchema,schema=>{
  const previous={...input.value}
  if(schema?.properties?.previewLimit&&previous.previewLimit==null&&previous.limit!=null)previous.previewLimit=previous.limit
  const next:Record<string,unknown>={}
  for(const[key,field]of Object.entries(schema?.properties||{})){
    if(previous[key]!=null)next[key]=previous[key]
    else if(field.default!=null)next[key]=field.default
  }
  input.value=next
})
onBeforeUnmount(()=>{generation++;clearTimeout(pollTimer)})

watch(()=>authStore.user?.activeIdentityId,()=>{generation++;clearTimeout(pollTimer);running.value=false;execution.value=null;pendingRequest.value=null;tasks.value=[];models.value=[];activeExpert.value=null;currentResearch.value=null;detail.value=null;history.value=[];catalog.value={experts:[],skills:[],mcps:[]};options.value={plans:[],semesters:[],colleges:[],courses:[]};input.value={};question.value='';error.value='';if(authStore.user){void load();void loadHistory()}})
onMounted(async()=>{await load();void loadHistory();if(props.initialExpertId){const expert=catalog.value.experts.find(item=>item.id===props.initialExpertId);if(expert)start(expert)}})
</script>
